class Library:
    def __init__(self):
        self.catalog = {}
        self.history = {}

    def add_book(self, isbn: str, copies: int = 1) -> None:
        if not isbn:
            raise ValueError("ISBN cannot be empty")
        if not isinstance(copies, int) or copies <= 0:
            raise ValueError("Copies must be a positive integer")
        if isbn not in self.catalog:
            self.catalog[isbn] = {'copies': 0, 'loans': []}
        self.catalog[isbn]['copies'] += copies

    def check_out(self, isbn: str, borrower: str) -> None:
        if not borrower:
            raise ValueError("Borrower ID cannot be empty")
        if isbn not in self.catalog:
            raise KeyError("ISBN not in catalog")
        if self.catalog[isbn]['copies'] == 0:
            raise NoCopyAvailable("No copy available for checkout")
        self.catalog[isbn]['copies'] -= 1
        self.catalog[isbn]['loans'].append(borrower)
        if isbn not in self.history:
            self.history[isbn] = []
        self.history[isbn].append(("check_out", borrower))

    def return_book(self, isbn: str, borrower: str) -> None:
        if not borrower:
            raise ValueError("Borrower ID cannot be empty")
        if isbn not in self.catalog:
            raise KeyError("ISBN not in catalog")
        if borrower not in self.catalog[isbn]['loans']:
            raise LibraryError("Borrower has no copy of this book checked out")
        self.catalog[isbn]['copies'] += 1
        self.catalog[isbn]['loans'].remove(borrower)
        self.history[isbn].append(("return", borrower))

    def get_available(self, isbn: str) -> int:
        if isbn not in self.catalog:
            raise KeyError("ISBN not in catalog")
        return self.catalog[isbn]['copies']

    def get_loans(self, borrower: str) -> list[str]:
        if not borrower:
            raise ValueError("Borrower ID cannot be empty")
        loans = []
        for isbn, data in self.catalog.items():
            if borrower in data['loans']:
                loans.append(isbn)
        return loans

    def get_history(self, isbn: str) -> list[tuple[str, str]]:
        if isbn not in self.catalog:
            raise KeyError("ISBN not in catalog")
        return self.history.get(isbn, [])

    def get_books(self) -> list[str]:
        return list(self.catalog.keys())
